  L0 = (L0 % 360 + 360) % 360;
  const meanSun = L0 / 15;
  let eotHours = meanSun - ra;
  while (eotHours > 12) eotHours -= 24;
  while (eotHours < -12) eotHours += 24;
  return eotHours * 60;
